def shortestSuperstring(words: list[str]) -> str:
    n = len(words)
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                cost[i][j] = len(words[j])
                for k in range(min(len(words[i]), len(words[j])), 0, -1):
                    if words[i][-k:] == words[j][:k]:
                        cost[i][j] = len(words[j]) - k
                        break
    memo = {}
    def tsp(mask, u):
        if mask == (1 << n) - 1: return (0, [])
        if (mask, u) in memo: return memo[(mask, u)]
        best_val = float('inf')
        best_path = []
        for v in range(n):
            if not (mask & (1 << v)):
                c = cost[u][v] if u != -1 else len(words[v])
                sub_c, sub_p = tsp(mask | (1 << v), v)
                if c + sub_c < best_val:
                    best_val = c + sub_c
                    best_path = [v] + sub_p
        memo[(mask, u)] = (best_val, best_path)
        return memo[(mask, u)]
    _, path = tsp(0, -1)
    res = words[path[0]]
    for i in range(1, len(path)):
        u, v = path[i-1], path[i]
        c = cost[u][v]
        res += words[v][len(words[v])-c:]
    return res

